</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private int selectedChannelId;
    private string currentChannelName = string.Empty;
    private string currentChannelDescription = string.Empty;

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    private bool isLoadingMore;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        var channel = channels.First(c => c.Id == channelId);
        currentChannelName = channel.Name;
        currentChannelDescription = channel.Description;

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        threadSummaries = BuildThreadSummaries(messages);
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update local unread count
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            threadSummaries = BuildThreadSummaries(messages);
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(sent);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary count
        var existing = threadSummaries.FirstOrDefault(t => t.RootMessageId == threadRootMessage.Id);
        if (existing is not null)
        {
            threadSummaries.Remove(existing);
            threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, existing.ReplyCount + 1, DateTime.UtcNow));
        }
        else
        {
            threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, 1, DateTime.UtcNow));
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update local state
        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var reaction = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (reaction is not null)
            {
                reaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, new List<string> { "You" }));
            }
        }
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> msgs)
    {
        // Group replies by their ReplyToId to build summaries
        return msgs
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}

